$sql='SELECT p.*,e.id employee_pk,e.employee_id employee_code,e.first_name,e.last_name,e.email,e.designation,d.department_name FROM payslips p JOIN employees e ON e.id=p.employee_id LEFT JOIN departments d ON d.id=e.department_id WHERE p.id=?';$q=$pdo->prepare($sql);$q->execute([$id]);$p=$q->fetch();$self=current_employee();if(!$p||($role!=='admin'&&(!$self||(int)$p['employee_pk']!==(int)$self['id']))){http_response_code(404);exit('Payslip not found.');}
