1;border:0;box-shadow:none}.slip-meta,.slip-note,.slip-head p{color:#555}.slip th,.slip td{border-color:#ddd}.slip-actions{display:none}}</style></head><body><div class="slip-actions"><a class="button secondary" href="<?=e($base.'/'.$role.'/payroll.php')?>">← Back to payroll</a><button class="button primary" type="button" onclick="window.print()">Print or save as PDF</button></div><article class="slip"><header class="slip-head"><div><span class="eyebrow">EMPLOYMENT MANAGEMENT SYSTEM</span><h1>Salary payslip</h1><p><?=e($period)?></p></div><div style="text-align:right"><b><?=e($p['employee_code'])?></b><p>Pay date · <?=e(date('M j, Y',strtotime($p['pay_date'])))?></p><p><?=e($p['payable_days'])?> of <?=e($p['scheduled_days'])?> scheduled workdays</p></div></header><div class="slip-meta"><div>Employee<b><?=e($p['first_name'].' '.$p['last_name'])?></b></div><div>Designation<b><?=e($p['designation'])?></b></div><div>Department<b><?=e($p['department_name']??'—')?></b></div><div>Work email<b><a class="contact-link" href="mailto:<?=e($p['email'])?>"><?=e($p['email'])?></a></b></div></div><table><thead><tr><th>EARNINGS</th><th>AMOUNT</th></tr></thead><tbody><tr><td>Basic salary</td><td><?=$money($p['basic_salary'])?></td></tr><tr><td>Dearness allowance</td><td><?=$money($p['dearness_allowance'])?></td></tr><tr><td>House rent allowance (HRA)</td><td><?=$money($p['hra'])?></td></tr><tr><td>Other fixed allowances</td><td><?=$money($p['other_allowances'])?></td></tr><tr><td>Other earnings / incentive</td><td><?=$money($p['other_earnings'])?></td></tr><tr><td><b>Gross earnings</b></td><td><b><?=$money($p['gross_salary'])?></b></td></tr></tbody></table><table style="margin-top:26px"><thead><tr><th>DEDUCTIONS</th><th>AMOUNT</th></tr></thead><tbody><tr><td>Employee provident fund (<?=e(number_format((float)$p['epf_rate'],0))?>% of eligible wage ₹<?=number_format((float)$p['pf_wage'],2)?>)</td><td><?=$money($p['employee_pf'])?></td></tr><tr><td>Gujarat professional tax</td><td><?=$m